def compute(vars):
    old_value = vars["v1"]
    new_value = vars["v2"]

    if old_value == 0:
        return None

    change = new_value - old_value
    percentage_change = (change / old_value) * 100

    return {
        "value": percentage_change,
        "trace": {
            "old_value": old_value,
            "new_value": new_value,
            "change": change,
            "output_meta": {
                "currency": None,
                "scale": "percent",
                "unit": "percentage"
            }
        }
    }
